const ids = ["TRATOR-01","TRATOR-02","TRATOR-03","SEMEADORA-01","SEMEADORA-02","SEMEADORA-03","PLANTADEIRA-01","PLANTADEIRA-02","PLANTADEIRA-03","COLHEITA-01","COLHEITA-02","COLHEITA-03"];
if (msg.topic === 'iniciar') {
    context.set('executando', true);
    context.set('ultimoInstante', Date.now());
    node.status({fill:'green',shape:'dot',text:'12 maquinas: a cada 5 s'});
    return null;
}
if (msg.topic === 'pausar') {
    context.set('executando', false);
    node.status({fill:'grey',shape:'ring',text:'pausado'});
    return null;
}
if (context.get('executando') !== true) return null;
const agora = Date.now();
const anterior = context.get('ultimoInstante') || agora;
const dt = Math.max(0, Math.min(10, (agora - anterior) / 1000));
context.set('ultimoInstante', agora);
let estados = context.get('maquinas') || {};
const limitar = (v,a,b) => Math.max(a,Math.min(b,v));
const arred = v => Math.round(v*1000)/1000;
const variar = (v,alvo,taxa,ruido) => v + limitar((alvo-v)*0.12 + (Math.random()-0.5)*ruido, -taxa*dt, taxa*dt);
const sequencia = (context.get('sequencia') || 0) + 1;
context.set('sequencia', sequencia);
const lote = msg._msgid || (agora.toString(36) + '-' + Math.random().toString(36).slice(2));
const mensagens = ids.map((id,i) => {
    let e = estados[id];
    if (!e) e = {ar:299+(i%3)*0.4,processo:310+(i%3)*0.4,carga:0.4+(i%3)*0.04,rpm:1550+(i%3)*20,torque:40,desgaste:20+i*7,tempo:0};
    e.tempo += dt;
    const cargaAlvo = 0.45 + 0.1*Math.sin(e.tempo/90+i);
    e.carga = limitar(variar(e.carga,cargaAlvo,0.006,0.015),0.25,0.65);
    e.ar = limitar(variar(e.ar,299.5+0.6*Math.sin(e.tempo/300+i/3),0.01,0.03),297,303);
    e.processo = limitar(variar(e.processo,e.ar+10.5+e.carga,0.03,0.04),e.ar+9,e.ar+13);
    e.rpm = limitar(variar(e.rpm,1650-200*e.carga,8,12),1400,1750);
    e.torque = limitar(variar(e.torque,30+25*e.carga,0.4,0.5),30,50);
    e.desgaste = Math.min(240,e.desgaste+dt/60);
    estados[id] = e;
    return {topic:'planta/maquina1/dados',payload:{messageId:lote+'-'+sequencia+'-'+id,machineId:id,timestamp:new Date(agora).toISOString(),type:'M',airTemperature:arred(e.ar),processTemperature:arred(e.processo),rotationalSpeed:arred(e.rpm),torque:arred(e.torque),toolWear:arred(e.desgaste)}};
});
context.set('maquinas',estados);
return [mensagens];
